<script lang="ts">
 import QRCode from 'qrcode'; let url='';let svg='';let mode='qr';let shortUrl='';let error='';let working=false;
 async function qr(v:string){url=v;if(v&&mode==='qr')svg=await QRCode.toString(v,{type:'svg',margin:2});else svg=''}
 async function shorten(){working=true;try{let r=await fetch('/api/shorten',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});let d=await r.json();if(!r.ok)throw Error(d.error);shortUrl=d.shortUrl}catch(e){error=e instanceof Error?e.message:'Ralat'}finally{working=false}}
</script>
<main><header>qora <small>privacy-first</small></header><section><div class="mark">⌘</div><h1>Pautan, dipermudah.</h1><p>Jana QR secara terus atau pendekkan pautan anda.</p><nav><button on:click={()=>{mode='qr';qr(url)}} class:active={mode==='qr'}>Jana QR</button><button on:click={()=>{mode='shorten';svg=''}} class:active={mode==='shorten'}>Pendekkan</button></nav><div class="entry"><input value={url} on:input={e=>qr(e.currentTarget.value)} placeholder="tampal pautan di sini"/>{#if mode==='shorten'}<button on:click={shorten}>{working?'…':'Pendekkan'}</button>{/if}</div>{#if svg}<div class="qr">{@html svg}</div>{/if}{#if shortUrl}<code>{shortUrl}</code>{/if}{#if error}<em>{error}</em>{/if}</section></main>
<style>main{min-height:100dvh}header{height:56px;border-bottom:1px solid #eee;padding:18px 5%;font-weight:700}small{float:right;color:#999;font-weight:400}section{width:min(90%,600px);margin:auto;padding:56px 0;text-align:center}.mark{font-size:48px}h1{font-size:clamp(2.6rem,8vw,4.5rem);letter-spacing:-.07em;margin:20px 0 8px}p{color:#777}nav{margin:30px auto 18px}button{border:1px solid #ddd;border-radius:9px;padding:10px 15px;background:#fff;font-weight:600}.active{background:#111;color:#fff}.entry{display:flex;gap:8px}.entry input{height:56px;min-width:0;flex:1;padding:0 16px;border:1px solid #bbb;border-radius:12px;font-size:15px}.entry button{background:#111;color:#fff;border:0}.qr{width:min(250px,72vw);margin:24px auto;padding:15px;border:1px solid #ddd;border-radius:18px}.qr :global(svg){width:100%;height:100%}code{display:block;margin:20px;padding:12px;border:1px solid #ddd;border-radius:8px;overflow:hidden;text-overflow:ellipsis}em{color:#b22}@media(max-width:600px){section{padding:42px 0}.entry{flex-direction:column}.entry button{height:52px}}</style>
